inline constexpr char kFontDay[] = R"WY_SHADER(

cbuffer NativeFontAbi:register(b0) {
 float4 fontProperties; float4 fontFill; float4 fontEdge; float4 fontStyle;
};
Texture2D<float4> glyphAtlas:register(t0);
SamplerState glyphSampler:register(s0);
struct FontInput { float4 pos:SV_Position; float4 uv:TEXCOORD0; float4 color:TEXCOORD3; };
float median3(float3 v) { return max(min(v.r,v.g),min(max(v.r,v.g),v.b)); }
float4 premultiply(float4 c) { return float4(c.rgb*c.a,c.a); }
float4 main(FontInput i):SV_Target {
 float4 fill=i.color*fontFill, edge=i.color*fontEdge;
 bool knownMapFont=all(abs(fontProperties.xyz-float3(64.0,32.0,5.937496))<0.0002) || all(abs(fontProperties.xyz-float3(512.0,512.0,7.544114))<0.0002) || all(abs(fontProperties.xyz-float3(512.0,512.0,7.661761))<0.0002) || all(abs(fontProperties.xyz-float3(512.0,512.0,11.908326))<0.0002) || all(abs(fontProperties.xyz-float3(1024.0,512.0,7.639702))<0.0002) || all(abs(fontProperties.xyz-float3(1024.0,512.0,7.772055))<0.0002) || all(abs(fontProperties.xyz-float3(4096.0,4096.0,7.295829))<0.0002) || all(abs(fontProperties.xyz-float3(4096.0,4096.0,9.441661))<0.0002) || all(abs(fontProperties.xyz-float3(4096.0,8192.0,8.549994))<0.0002);
 float brightest=max(fill.r,max(fill.g,fill.b));
 float darkest=min(fill.r,min(fill.g,fill.b));
 // Native dark labels and the teal-green city labels need a theme fill.
 // Teal matching additionally requires the native black map-outline style.
 // Pure green status text, white labels, orange labels and other fonts pass through.
 bool darkNeutral=brightest<=0.06 && brightest-darkest<=0.01;
 bool mapOutline=all(abs(fontEdge.rgb)<0.0001) && abs(fontStyle.x-0.607143)<0.0002;
 bool cityGreen=fill.g>0.04 && fill.g>fill.b*1.12 && fill.b>fill.r*1.10;
 bool themeLabel=knownMapFont && (darkNeutral || (mapOutline && cityGreen));
 float4 ink=premultiply(fill), rim=premultiply(edge);
 if(themeLabel) {
  ink.rgb=float3(0.0144438436,0.01520851442,0.01764195449)*fill.a;
  rim.rgb=float3(1,1,1)*edge.a;
 }
 float2 derivativeX=ddx(i.uv.xy), derivativeY=ddy(i.uv.xy);
 float ratio=dot(fontProperties.xy,abs(derivativeX)+abs(derivativeY))*0.5;
 int samples=(int)clamp(2*floor(ratio),1,4);
 float2 texelStep=float2(derivativeX.x,derivativeY.y);
 float2 glyphStep=float2(ddx(i.uv.z),ddy(i.uv.w));
 float2 uvPerGlyph=texelStep/glyphStep;
 float4 bounds=i.uv.xyxy+float4(-i.uv.zw,1-i.uv.zw)*uvPerGlyph.xyxy;
 float2 subStep=texelStep/samples;
 float2 origin=i.uv.xy-0.5*texelStep+0.5*subStep;
 float feather=min(2/fontProperties.z,ratio/(2*fontProperties.z))/samples;
 float threshold=fontProperties.w+fontStyle.x;
 float low=-feather-threshold, high=feather-threshold;
 float4 sum=0;
 [loop] for(int x=0;x<samples;x++) [loop] for(int y=0;y<samples;y++) {
  float2 uv=clamp(origin+float2(x,y)*subStep,bounds.xy,bounds.zw);
  float distance=2*median3(glyphAtlas.SampleLevel(glyphSampler,uv,0).rgb)-1;
  float fillCoverage=saturate((distance-fontStyle.x-low)/(high-low));
  float edgeCoverage=saturate((distance-low)/(high-low));
  sum+=lerp(rim*edgeCoverage,ink,fillCoverage);
 }
 return sum/(samples*samples);
}

)WY_SHADER";
